// New test case to check for SystemExit error when pysemver command is invoked without arguments
    def test_pysemver_without_args(self):
        with self.assertRaises(SystemExit):
            pysemver.cli()

// New test case to check for help text when bump subcommand is called without specific arguments
    def test_bump_without_args(self):
        sys.argv = [__file__, 'bump']
        pysemver.cli()
        self.assertIn('Usage:', sys.stdout.getvalue())
